## RENAMED Requirements
- FROM: `### Requirement: Old name`
- TO: `### Requirement: New name`

## REMOVED Requirements
### Requirement: Old name              <- header form (raw block kept as removedBlocks)
- `### Requirement: Other old name`    <- bullet form; any of - * + accepted

// requirement-blocks.ts
const REQUIREMENT_HEADER_REGEX = /^###\s*Requirement:\s*(.+)\s*$/i;
fromMatch = line.match(/^\s*[-*+]?\s*FROM:\s*`?###\s*Requirement:\s*(.+?)`?\s*$/);
toMatch   = line.match(/^\s*[-*+]?\s*TO:\s*`?###\s*Requirement:\s*(.+?)`?\s*$/);
bullet    = line.match(/^\s*[-*+]\s*`?###\s*Requirement:\s*(.+?)`?\s*$/);   // REMOVED bullets
// a FROM must be followed by its TO (no second FROM between); anything else lands in plan.unpairedRenames

// pre-validate: duplicates inside a section; cross-section conflicts; RENAMED vs MODIFIED/ADDED/REMOVED;
//               'Delta parsing found no operations for <id>. Provide ADDED/MODIFIED/REMOVED/RENAMED sections in change spec.'
// base: target spec missing -> only ADDED allowed (MODIFIED/RENAMED throw), REMOVED warns+ignored, skeleton built:
//       `# ${id} Specification\n\n## Purpose\n${purpose or 'TBD - created by archiving change X. Update Purpose after archive.'}\n\n## Requirements\n`
nameToBlock = Map(normalizedName -> block of main spec); orderedKeys = original order
// Apply operations in order: RENAMED -> REMOVED -> MODIFIED -> ADDED
RENAMED : source missing & target present -> no-op (already synced); both missing -> throw; target exists -> throw
          header line rewritten in place; block keeps its original position (orderedKeys[i] = to)
REMOVED : missing -> warn 'treating it as already removed' (near-miss by case/space -> throw)
MODIFIED: missing -> throw ' - not found'; header mismatch -> throw; scenario names missing vs current -> throw;
          whole block replaced by delta raw; identical content -> counted as no-op
ADDED   : identical existing -> skip; different existing -> throw 'already exists'; near-miss name -> throw
// recompose: keep original order (replacements in place), append new ADDED at end, join blocks with blank line
// returns {rebuilt, counts{added,modified,removed,renamed}, warnings[], noRequirementBlocks, unaccountedContent[]}
